import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第五卷 答案 · 第112章 商量","description":"","frontmatter":{},"headers":[],"relativePath":"第112章_商量.md","filePath":"第112章_商量.md"}'),r={name:"第112章_商量.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第五卷-答案-·-第112章-商量" tabindex="-1">第五卷 答案 · 第112章 商量 <a class="header-anchor" href="#第五卷-答案-·-第112章-商量" aria-label="Permalink to &quot;第五卷 答案 · 第112章 商量&quot;">​</a></h1><p>后街夜市的人声是烫的。</p><p>灯泡一串连着一串，照在塑料棚上，照出油亮的光。风一吹，棚布轻轻鼓起来，又落下去，带着炒锅里的焦香，往我脸上扑。</p><p>我到的时候，周野已经占好了那张老乡小桌。</p><p>桌子很小，三个人坐正好，多一个人就要碰胳膊肘。桌面上有一层薄薄的油，被他用纸巾擦了两遍，纸巾团放在一旁，皱巴巴的。</p><p>“坐啊。”他抬头看我，把面前的糖水往我这边推了推，“刚上的，还热。”</p><p>糖水是南雾口味的，汤色清亮，里面浮着小圆子，还有切碎的薯块。热气往上走，带着甜味，落到眼睛上，有点潮。</p><p>我坐下来，捧住碗，先喝了一口。甜，烫，喉咙一下子就暖了。</p><p>“温棠呢。”我问。</p><p>“后面呢，说要去买纸巾。”周野咬了一口蒜，“这家炒面今天人多，师傅手都抡出影子了。”</p><p>果然，旁边的铁锅哗啦一声响，火苗蹿起来半尺高。师傅把面抛起来，又接住，面条在空中散开，又落回去。油烟混着酱香，一下子就散开了。我闻得到锅气，还有隔壁桌飘来的辣酱味。</p><p>风里有汗味，有甜味，还有远处雾山大学晚课散场后，自行车铃铛的脆响。</p><p>温棠就是这个时候来的，手里拿着一包纸巾，额头上有一层汗。</p><p>“挤死了。”她坐下来，喘了口气，拿纸巾擦了擦手，“你们点了吗。”</p><p>“点了两份炒面。”周野说，“糖水先喝着。”</p><p>温棠端起糖水喝了一口，眼睛弯起来：“还是这个味道，在南州外院那边喝不到。”</p><p>我点点头，没接话，手指在碗沿上轻轻摩挲。碗很烫，烫得指尖发麻，我却不想放开。</p><p>炒面很快上来了，两大盘，堆得冒尖。面条根根分明，裹着酱色，上面撒着葱花和豆芽，还有几片薄薄的肉。热气直往上冒，我夹了一筷子，吹了吹，送进嘴里。咸香里带着一点焦，豆芽是脆的，嚼起来咯吱响。</p><p>三个人一时都没说话，只有筷子碰到盘子的声音。</p><p>我知道今晚是我把他们叫出来的，我得先开口。</p><p>“有件事，想跟你们商量一下。”我说。</p><p>周野抬头：“你说。”</p><p>温棠也放下筷子，看着我。</p><p>夜市的光落在她脸上，照出很亮的一小块，又很快暗下去。</p><p>“小说，先不送了。”我说，“等风头过一过再说。”</p><p>周野愣了一下：“怎么了，之前都包好了。”</p><p>我把糖水往旁边挪了挪，腾出一小块桌面。手指在桌上轻轻敲了两下。</p><p>“她阿婆病倒了。”我说得很慢，“前两天夜里起不来，邻居帮忙送去看的。现在在老街家里躺着，要人看着。”</p><p>温棠的表情一下子变了：“严重吗。”</p><p>“老人家底子弱，要养。”我说，“我这几天都住在老街，陪着她。晚上她睡不踏实，我就坐在门口，听着屋里的动静。”</p><p>周野皱起眉：“那你还跑出来吃夜宵。”</p><p>“就是因为在屋里闷久了，想出来透口气。”我笑了笑，“再说，有些话，当面说才清楚。”</p><p>炒锅那边又是一声响，油星子噼啪的。有人端着盘子从我们身后挤过去，带起一阵风，把桌上的纸巾吹得翻了个面。</p><p>温棠把纸巾压住，轻声问：“是怕连累大家吗。”</p><p>我点点头，又摇摇头。</p><p>“一半一半吧。”我说，“最近问我情感史的人变多了，话传来传去，容易走样。我不想在这个时候，把小说递出去，让人拿着放大看。”</p><p>周野往嘴里塞了一口面，嚼了几下，咽下去，才开口：“是因为平安结的事。”</p><p>我没否认。</p><p>那只平安结，是我很早以前编的。红绳，纸星星做点缀，里面还藏了一小段磁带上的丝带。那是我跟着随身听里的歌，一点点学着编的。针脚不齐，结也打得歪，可我一直留着。</p><p>前阵子，我把它送了出去，后来，又被退了回来。</p><p>退回来的时候，绳子散了一半，纸星星皱了，放在信封里，轻飘飘的，没什么分量。</p><p>我把它拿在手里看了很久，又放进了抽屉。</p><p>“被退了，我认。”我说，“东西送出去，人家收不收，都是自由。只是这件事一传，味道就变了。有人说我纠缠，有人说我作秀。我不想解释，解释多了，更像有事。”</p><p>温棠咬着嘴唇：“你本来就没那个意思。”</p><p>“我知道你们知道。”我说，“可夜市的话，风一吹就散，散到哪算哪。我不想让老乡小桌也被卷进去。咱们就吃个糖水，吃个炒面，挺好的，没必要被人指点。”</p><p>周野把筷子放下来，发出很轻的一声响。</p><p>“沈聿。”他看着我，“你老实说，你是怕小说连累她阿婆，还是怕小说连累江苒。”</p><p>我夹面的手停在半空。</p><p>热气还在往上走，模糊了他的脸。豆芽的脆香还在，糖水的甜还在，可嘴里忽然有点发苦。</p><p>“我都怕。”我说。</p><p>老街的夜，我从温棠嘴里又听熟了。她阿婆睡在里屋，江苒睡在外间，床板硬，她不敢翻身。半夜老人咳嗽，她就起来倒水，扶她喝下，等她睡沉了才回去。</p><p>白天她去买菜，青菜带着水，拎回来，她阿婆就靠在门口看她。</p><p>半留守的日子，就是这样。我跟奶奶住在旧楼，守着小屋，守着随身听里的旧磁带，守着窗台上那罐纸星星。</p><p>“她阿婆知道小说的事吗。”温棠问。</p><p>“知道一点。”我说，“她说，东西是好的，就别急着送人。先放放，放放也好。”</p><p>周野叹了口气，端起糖水喝了一大口。</p><p>“行。”他说，“那就先不送，等风头过。我们都听你的。”</p><p>温棠点点头：“风头过的意思，是等大家忘了平安结的事，还是等她阿婆好起来。”</p><p>“都等。”我说，“等她阿婆能下地走走，等夜市的人换个话题，等我自己心里静下来。现在送，我心不静，东西也送不好。”</p><p>“那要等到什么时候。”周野问。</p><p>我摇摇头：“说不好。也许十天半个月，也许更久。我就是先跟你们通个气，免得你们还惦记着帮我跑腿。”</p><p>温棠伸手过来，轻轻碰了碰我的手背。她的手指凉凉的，带着糖水的甜香。</p><p>“我们不急。”她说，“你多顾着她一点就行。炒面不够再点，别饿着。”</p><p>我心里一酸，又很快压下去，低头吃面。面已经有点坨了，缠在一起，酱色更浓。我大口吃着，豆芽还是脆的，葱花香得很实在。</p><p>吃着吃着，眼眶有点热，被热气熏的。</p><p>周野见我不说话，故意换了话题：“你们知道吗，顾远前两天还问我，小说封面要不要帮忙画个边。我说你先别画了，人家作者要雪藏了。”</p><p>温棠笑了一下，说她昨天还琢磨，纸星星要不要再折一点，放进书里当书签。我说先别折了，留着吧。</p><p>我跟着笑：“替我谢谢他们。”</p><p>夜市正热闹，隔壁桌碰了下啤酒瓶，声音清脆。风里全是活气。</p><p>我捧着糖水，慢慢喝完最后一口。碗底剩了两颗小圆子，圆滚滚的，贴在碗壁上。我用勺子把它们舀起来，吃掉，甜味在嘴里化开。</p><p>“说好了啊。”我抬起头，看着他们两个，“先不送，等风头过。这段时间，谁问起来，你们就说不知道。”</p><p>“知道。”周野点头，“我们嘴严。”</p><p>温棠也点头，又有点犹豫：“那要是江苒问起来呢。”</p><p>我的心跳漏了一拍。</p><p>筷子还夹着面，停在半空，酱汁滴下来，落在盘子里，晕开一小点。</p><p>“她不会问的。”我说，声音比刚才低，“我们已经分开了，她有她的事。”</p><p>周野和温棠对视了一眼，没再说话。</p><p>就在这时，温棠放在桌上的手机亮了一下，屏幕的光在夜市的灯下很淡，却晃了我的眼。</p><p>她拿起来看了一眼，眉头微微一动，又很快放下，扣在桌上。</p><p>“怎么了。”我问。</p><p>她看了看周野，又看了看我，嘴唇动了动，似乎想说什么，又咽了回去。</p><p>夜市的风忽然大了，把棚布吹得哗哗响，炒锅的火苗歪向一边，糖水的热气一下子散了。</p><p>我盯着她扣在桌上的手机，心里慢慢沉下去。</p>',83)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
